/*
 Problem: 1190. Reverse Substrings Between Each Pair of Parentheses
 Language: cpp
 Runtime: 2 ms (43.75%)
 Memory: 10.5 MB (27.47%)
 Tags: String, Stack, Bracket Sequences
*/
class Solution {
public:
    string reverseParentheses(string s) {
        vector<string> st;
        string cur;

        for (const auto& c : s) {
            if (c == '(') {
                st.push_back(cur);
                cur.clear();
            } else if (c == ')') {
                reverse(cur.begin(), cur.end());
                cur = st.back() + cur;
                st.pop_back();
            } else {
                cur += c;
            }
        }

        return cur;
    }
};
